package thaumcraft.verification;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.block.*;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.tick.ServerTickEvent;import thaumcraft.world.*;import thaumcraft.registry.*;
/** Fresh ordinary terrain with the user's C2ME build, no prepared surfaces or forced decoration rolls. */
final class BiomeGenerationVerification {
 final MinecraftServer server;final ServerLevel level;int ticks,stage,index;ChunkPreparation chunks;BlockPos taint;final List<String> checks=new ArrayList<>();final Map<String,Object> data=new LinkedHashMap<>();
 static Path root(){return Path.of(System.getProperty("thaumcraft.r3.root"),".cache/biome-followup-2026-10-17");}
 BiomeGenerationVerification(MinecraftServer s){server=s;level=s.overworld();}
 static void register(MinecraftServer s){var v=new BiomeGenerationVerification(s);NeoForge.EVENT_BUS.addListener(v::tick);}
 void check(boolean value,String label){if(!value)throw new AssertionError(label);checks.add(label);System.out.println("BIOME_CHECK "+label);}
 void tick(ServerTickEvent.Post event){if(event.getServer()!=server)return;try{ticks++;if(ticks>12000)throw new AssertionError("biome verification timed out");if(stage==0){check(net.neoforged.fml.ModList.get().isLoaded("c2me"),"actual user C2ME build is loaded");chunks=new ChunkPreparation(level,20392>>4,20392>>4,19448>>4,19448>>4);stage=1;}
 if(stage==1){if(!chunks.advance(4))return;var chunk=level.getChunk(20392>>4,19448>>4);boolean mound=chunk.getAllStarts().values().stream().anyMatch(s->s.isValid()&&s.getStructure() instanceof NativeStructures.Site site&&site.kind==NativeStructures.Kind.MOUND);check(mound,"mound FEATURES completes with C2ME thread ownership checks enabled");chunks.close();int x=23464>>4,z=15912>>4;chunks=new ChunkPreparation(level,x-3,x+3,z-3,z+3);stage=2;}
 if(stage==2){if(!chunks.advance(6))return;int biome=0,trees=0,special=0;int cx=23464>>4,cz=15912>>4;for(int x=(cx-3)*16;x<(cx+4)*16;x++)for(int z=(cz-3)*16;z<(cz+4)*16;z++){int top=level.getHeight(Heightmap.Types.MOTION_BLOCKING,x,z);if(!level.getBiome(new BlockPos(x,top,z)).is(WorldBiomes.MAGICAL))continue;biome++;for(int y=top;y>=top-40;y--){var p=new BlockPos(x,y,z);var state=level.getBlockState(p);if(state.is(net.minecraft.tags.BlockTags.LOGS)&&level.getBlockState(p.below()).is(net.minecraft.tags.BlockTags.DIRT)){trees++;if(state.is(R3Content.GREATWOOD_LOG.get())||state.is(R3Content.SILVERWOOD_LOG.get())||state.is(R3Content.SILVERWOOD_NODE_LOG.get()))special++;break;}}}data.put("forestBiomeColumns",biome);data.put("forestGroundedTrunkColumns",trees);data.put("forestSpecialTrunkColumns",special);data.put("forest",List.of(23464,level.getHeight(Heightmap.Types.MOTION_BLOCKING,23464,15912),15912));check(biome>128&&trees>=32,"fresh magical forest has a canopy with many grounded trees under C2ME: "+trees);check(special>0,"fresh magical forest includes actual greatwood or silverwood trunks");chunks.close();chunks=null;stage=3;}
 if(stage==3){var g=level.getChunkSource().getGenerator();var r=level.getChunkSource().randomState();for(int i=0;i<64;i++){int n=index++,x=20008+(n%64-32)*128,z=20008+(n/64-32)*128;int y=g.getBaseHeight(x,z,Heightmap.Types.WORLD_SURFACE_WG,level,r);if(g.getBiomeSource().getNoiseBiome(x>>2,y>>2,z>>2,r.sampler()).is(WorldBiomes.TAINT)){taint=new BlockPos(x,y,z);break;}}if(taint==null){check(index<4096,"natural tainted land exists");return;}var p=new ChunkPos(taint);chunks=new ChunkPreparation(level,p.x-3,p.x+3,p.z-3,p.z+3);stage=4;}
 if(stage==4){if(!chunks.advance(6))return;int biome=0,fibres=0,trees=0,rocks=0;var c=new ChunkPos(taint);for(int x=(c.x-3)*16;x<(c.x+4)*16;x++)for(int z=(c.z-3)*16;z<(c.z+4)*16;z++){int top=level.getHeight(Heightmap.Types.MOTION_BLOCKING,x,z);if(!level.getBiome(new BlockPos(x,top,z)).is(WorldBiomes.TAINT))continue;biome++;for(int y=top+2;y>=Math.max(0,top-40);y--){var at=new BlockPos(x,y,z);var state=level.getBlockState(at);if(state.is(R2Content.TAINT_FIBRES.get()))fibres++;if(state.is(Blocks.MOSSY_COBBLESTONE))rocks++;if(state.is(net.minecraft.tags.BlockTags.LOGS)&&level.getBlockState(at.below()).is(net.minecraft.tags.BlockTags.DIRT))trees++;}}data.put("taintBiomeColumns",biome);data.put("taintFibreBlocks",fibres);data.put("taintGroundedTrunkColumns",trees);data.put("taintMossyBoulderBlocks",rocks);data.put("taint",List.of(taint.getX(),taint.getY(),taint.getZ()));check(biome>128&&fibres>=10,"fresh tainted land has actual fibre blocks, not only biome tint: "+fibres);check(trees>0&&rocks>0,"fresh tainted land has original trees and mossy boulders");check(!R4Content.OBSIDIAN_TOTEM.get().defaultBlockState().hasBlockEntity(),"plain totem body does not save empty block entities");finish(null);}
 }catch(Throwable error){error.printStackTrace();finish(error);}}
 void finish(Throwable error){if(chunks!=null)chunks.close();try{Files.createDirectories(root());data.put("passed",error==null);data.put("finished",true);data.put("checks",checks);data.put("ticks",ticks);if(error!=null)data.put("error",error.toString());Files.writeString(root().resolve("result.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(data));server.saveEverything(false,true,true);}catch(Exception ex){throw new RuntimeException(ex);}finally{server.halt(false);}}
}
